  CHECK_FIX_AUTHORING,
  DIAGNOSIS_COMMENT_MARKER,
  FIX_CHECK_NAME,
  FIX_TITLE_PREFIX,
  FIX_WORKFLOW_FILE,
  MAX_CORRECTION_ROUNDS,
  MAX_STALLED_ROUNDS,
  ORCHESTRATE_WORKFLOW_FILE,
  PREPARE_WORKFLOW_FILE,
  SPEC_BRANCH_PREFIX,
  baseBranchOf,
  defaultBranchOf,
  explainDependencyBlock,
