// Specs authored by `/speckit author`: when a diagnosis finds the cause of a stop outside the stopped spec (code or
// tests of another feature on the base branch, or the environment actions), the GitHub workflow Spec Kit author
// (speckit-author.yml) authors an ordinary, complete spec that removes it and proposes it as a pull request from
// speckit-spec/<folder> against the default branch (pull requests opened earlier use speckit-fix/<folder>). Its job
// `author` (read-only) lets one decision step (decision.json: reuse, refuse, or author with a feature description)
// run before the deterministic Spec Kit workflow `author` (.specify/extension-src/gha/workflows/author/) writes the
// spec unattended; its job `land` publishes the result and records it (runLand, runRecord). The spec runs
// through the same consistency check and correction rounds as an amendment (speckit-amend.mjs, kind `fix`); a
// consistent one that changes no architecture and that no person pushed to or requested changes on is merged
// automatically (mergeSpecPull), otherwise it is handed to a person for review. Once merged, its twin goes through
// dependency inference like any twin, and the scheduler makes the stopped spec depend on it. Like every spec it starts
// only once someone signs it off with `/speckit implement` on its twin. Blocking and retrying the stopped
// implementation is the generic handling of open dependencies (maintainDependencyBlock). The lifecycle is recorded as
// markers in the workflow's comments on the implementation pull request (renderFixEvent).

export class FixUsageError extends Error {}

export const FIX_MODES = ['author', 'fix', 'revise'];
// An authoring run that has not reported after this long belongs to a cancelled or crashed run.
const AUTHORING_STALE_MS = 2 * 60 * 60 * 1000;
const MAX_EVIDENCE_BYTES = 150_000;

const clip = (text, max) => {
  const value = String(text ?? '');
  return value.length > max ? `${value.slice(0, max)}…` : value;
};

// The agent-written pull request description without HTML comments: they could forge Spec Kit markers, and gh-aw's
// footer markers only repeat its visible "Generated by" line. Escaped instead, they would show up as text.
export function withoutComments(text) {
  return neutralizeMarkers(String(text ?? '').replace(/<!--[\s\S]*?-->/g, '').replace(/[ \t]+$/gm, '').replace(/\n{3,}/g, '\n\n').trim());
}

// The UTC time prefix of a new spec folder (feature_numbering `timestamp`).
export function fixStamp(now = Date.now()) {
  const date = new Date(now);
  const pad = (value) => String(value).padStart(2, '0');
  return `${date.getUTCFullYear()}${pad(date.getUTCMonth() + 1)}${pad(date.getUTCDate())}-${pad(date.getUTCHours())}${pad(date.getUTCMinutes())}${pad(date.getUTCSeconds())}`;
}

// Why an implementation is blocked by the spec `/speckit author` authored for it before the dependency exists, for
// setBlocked: `review` while the spec pull request is open, `implement` once it is merged and its twin is not linked
// yet. Once the twin depends on it, the generic dependency block (explainDependencyBlock) explains the wait.
export function fixBlock({ stage, fixPull, fixTwin = null, baseBranch }) {
  const base = baseBranch ? `\`${baseBranch}\`` : 'the default branch';
  const twin = fixTwin ? `#${fixTwin}` : 'its spec twin';
  const lines = stage === 'review'
    ? [
      `**Blocked** by spec #${fixPull}: the cause of the stop lies outside this spec, so this implementation waits for that spec instead of trying again. Nothing is needed on this pull request.`,
      '',
      `- **Next**: #${fixPull} is checked for consistency and merged into ${base} automatically. When it changes \`docs/architecture/\` or a person pushed to it, it is handed to you for review instead. Once it is merged and signed off with \`/speckit implement\` on its spec twin, it is implemented; this implementation then retries by itself.`,
      `- **To rework the spec**: comment or request changes on #${fixPull}.`,
      `- **To drop the spec**: close #${fixPull} without merging; the block is lifted and this pull request lists what you can do next.`,
    ]
    : [
      `**Blocked** by spec #${fixPull}${fixTwin ? ` (spec twin #${fixTwin})` : ''}: it is merged and becomes a spec twin like any spec. Nothing is needed on this pull request yet.`,
      '',
      `- **Next**: once ${twin} exists, this spec depends on it, and this pull request names the twin with the command that signs it off for implementation (\`/speckit implement\`, commented on the twin).`,
      `- **Unblocks by itself** once ${twin} is implemented: this implementation then continues with a fresh attempt count.`,
      `- If ${twin} is closed without being implemented, the block is lifted and this pull request lists what you can do next.`,
    ];
  return { key: { pull: fixPull, stage }, lines };
}

// The latest prerequisite spec of an implementation pull request and what happened to it, from the workflow's comments.
// Specs that do not block the implementation (`link: false` in their events, such as a spec that makes a flaky test
// deterministic) have a lifecycle of their own: `unlinked` selects it.
export function fixState(comments, { unlinked = false } = {}) {
  const events = parseFixEvents(comments).filter((event) => (event.link === false) === unlinked);
  const created = events.filter((event) => event.event === 'created').at(-1) ?? null;
  const of = (name) => (created ? events.filter((event) => event.event === name && event.pull === created.pull).at(-1) ?? null : null);
  const requested = events.filter((event) => event.event === 'requested' && (!created || Date.parse(event.at) <= Date.parse(created.at))).at(-1) ?? null;
  return { events, requested, created, merged: of('merged'), discarded: of('discarded'), linked: of('linked'), landed: of('landed'), stopped: of('stopped') };
}

// The `/speckit author` request a spec pull request was authored for (the latest request before its `created` event
// with the same `link`), or null.
export function specRequest(comments, specPull) {
  const events = parseFixEvents(comments);
  const created = events.filter((event) => event.event === 'created' && event.pull === specPull).at(-1);
  if (!created) return null;
  return events.filter((event) => event.event === 'requested' && (event.link === false) === (created.link === false) && Date.parse(event.at) <= Date.parse(created.at)).at(-1) ?? null;
}

// The prerequisite spec pull requests that open implementation pull requests recorded (`created` events), by pull
// request number: the implementation each was authored for (`owner`, not one that joined it) and its folder.
async function recordedPrerequisites(client, pulls) {
  const found = new Map();
  for (const implementation of pulls) {
    if (!String(implementation.head?.ref ?? '').startsWith(BRANCH_PREFIX)) continue;
    for (const event of parseFixEvents(await client.listIssueComments(implementation.number))) {
      if (event.event !== 'created' || !Number.isInteger(event.pull)) continue;
      const item = found.get(event.pull) ?? { folder: event.folder, owner: null, implementations: [] };
      if (!event.joined) item.owner = implementation.number;
      if (!item.implementations.includes(implementation.number)) item.implementations.push(implementation.number);
      found.set(event.pull, item);
    }
  }
  return found;
}

// The implementation pull request a prerequisite spec pull request was authored for: the legacy marker in its
// description, or the open implementation pull request that recorded it.
export async function authoredFor(client, pull) {
  const legacy = parseFixFor(pull.body)?.pull;
  if (legacy) return legacy;
  return (await recordedPrerequisites(client, await client.listOpenPullRequests())).get(pull.number)?.owner ?? null;
}

// One cause gets one prerequisite spec. The prerequisite specs that may already cover a cause: open prerequisite spec
// pull requests against the default branch (both branch prefixes), and merged ones that an open implementation waits
// for and whose spec twin is still open (not implemented yet). `/speckit author` joins one of them instead of authoring a
// second spec for the same cause.
export async function existingFixSpecs(client, env) {
  const defaultBranch = defaultBranchOf(env);
  const open = await client.listOpenPullRequests();
  const recorded = await recordedPrerequisites(client, open);
  const found = [];
  for (const pull of open) {
    const folder = folderOfBranch(pull.head?.ref);
    if (!isPrerequisiteBranch(pull.head?.ref) || !folder || pull.base?.ref !== defaultBranch) continue;
    const spec = await client.getFileContent(`specs/${folder}/spec.md`, pull.head?.sha ?? pull.head?.ref);
    found.push({ pull: pull.number, title: pull.title ?? '', folder, state: 'open', twin: null, url: pull.html_url ?? '', fixFor: recorded.get(pull.number)?.owner ?? parseFixFor(pull.body)?.pull ?? null, spec });
  }
  const { byFolder } = resolveTwins(await client.listTwinIssues(TWIN_LABEL));
  for (const [number, item] of recorded) {
    if (found.some((entry) => entry.pull === number)) continue;
    const twin = byFolder.get(item.folder);
    if (!twin || twin.state !== 'open') continue;
    let merged;
    try {
      merged = await client.getPullRequest(number);
    } catch {
      continue;
    }
    if (!merged?.merged_at || merged.base?.ref !== defaultBranch || !isPrerequisiteBranch(merged.head?.ref)) continue;
    const spec = await client.getFileContent(`specs/${item.folder}/spec.md`, defaultBranch);
    found.push({ pull: number, title: merged.title ?? '', folder: item.folder, state: 'merged', twin: twin.number, url: merged.html_url ?? '', fixFor: item.owner ?? parseFixForLine(spec), spec });
  }
  return found.sort((a, b) => a.pull - b.pull);
}

// `/speckit author [guidance]`: records the request on the implementation pull request and starts the authoring run.
// The implementation keeps waiting. Refused while a spec authored for this implementation is being authored, open, or
// merged but not implemented yet. With `link: false` the spec does not block the implementation (the scheduler asks
// for one that makes a flaky test deterministic): its events carry `link: false`, it is never linked as a dependency
// of the twin, and it is refused only while another such spec is being authored or open.
export async function startFixAuthoring(client, env, { twin, implementation, guidance = '', actor, now = Date.now(), link = true }) {
  const folder = folderOfBranch(implementation.head?.ref);
  const baseBranch = baseBranchOf(implementation);
  const defaultBranch = defaultBranchOf(env);
  if (baseBranch !== defaultBranch) {
    return { started: false, reason: `the implementation's base branch \`${baseBranch}\` is not the default branch \`${defaultBranch}\`, where new specs are added` };
  }
  const state = fixState(await client.listIssueComments(implementation.number), { unlinked: !link });
  if (state.created && !state.discarded && !state.landed && !state.stopped) {
    const pull = await client.getPullRequest(state.created.pull);
    if (pull.state === 'open') return { started: false, reason: `spec #${pull.number} is still open for this cause; follow it there, or close it first` };
    const pending = link && (!state.linked || (await client.getIssue(state.linked.twin))?.state === 'open');
    if (pull.merged_at && pending) return { started: false, reason: `spec #${pull.number} was merged and is not implemented yet; this implementation retries by itself once it is implemented` };
  }
  const latest = latestCheckRun(await client.listCheckRuns(implementation.head.sha, FIX_CHECK_NAME));
  if (latest && latest.status !== 'completed') {
    if (now - Date.parse(latest.started_at ?? latest.created_at ?? 0) < AUTHORING_STALE_MS) return { started: false, reason: 'a new spec is already being authored' };
    await closeAuthoringCheck(client, latest.id, 'failure', 'The spec authoring did not finish', 'The run ended without a result.');
  }
  const stamp = fixStamp(now);
  const value = String(guidance ?? '').trim();
  const check = await client.createCheckRun({
    name: FIX_CHECK_NAME,
    head_sha: implementation.head.sha,
    status: 'in_progress',
    external_id: CHECK_FIX_AUTHORING,
    output: { title: 'Authoring a new spec', summary: `Requested by @${actor}.${link ? '' : ' It does not block this implementation.'}${value ? `\n\nGuidance: ${clip(value, 2000)}` : ''}` },
  });
  await client.createComment(implementation.number, [
    renderFixEvent('requested', { by: actor, stamp, ...(link ? {} : { link: false }) }),
    ...(value ? [renderGuidanceMarker(value)] : []),
    link
      ? `**A new spec is being authored**, requested by @${actor}. The Spec Kit workflow \`author\` writes an ordinary spec that removes the cause outside this spec and opens it as a pull request against \`${baseBranch}\`; it is checked for consistency and then merged automatically, or handed to you for review when it changes \`docs/architecture/\`. This implementation waits meanwhile.`
      : `**A new spec is being authored** for @${actor}. The Spec Kit workflow \`author\` writes an ordinary spec and opens it as a pull request against \`${baseBranch}\`; it is checked for consistency and then merged automatically, or handed over for review when it changes \`docs/architecture/\`. It does not block this implementation, which continues meanwhile.`,
    ...(value ? ['', 'Guidance for the decision:', '', ...neutralizeMarkers(value).split('\n').map((line) => `> ${line}`)] : []),
  ].join('\n'));
  try {
    await client.dispatchWorkflow(FIX_WORKFLOW_FILE, defaultBranch, {
      issue: String(twin),
      pull: String(implementation.number),
      folder,
      guidance: clip(value, 4000),
      check_run: String(check.id),
      mode: 'author',
      amendment: '',
      round: '0',
      stalls: '0',
      findings: '',
      stamp,
    });
    if (link) await setAttention(client, implementation.number, false);
    return { started: true, check, stamp };
  } catch (error) {
    await closeAuthoringCheck(client, check.id, 'failure', 'The spec authoring could not start', error.message);
    return { started: false, reason: `the authoring could not start: ${error.message}` };
  }
}

async function closeAuthoringCheck(client, id, conclusion, title, summary) {
  await client.updateCheckRun(id, { status: 'completed', conclusion, external_id: CHECK_FIX_AUTHORED, output: { title, summary: clip(summary || title, 2000) } });
}

function inputsFrom(env) {
  const twin = Number(env.SPECKIT_TWIN);
  const pull = Number(env.SPECKIT_PULL);
  const folder = String(env.SPECKIT_FOLDER ?? '');
  if (!Number.isInteger(twin) || twin <= 0 || !Number.isInteger(pull) || pull <= 0 || !isValidFolderName(folder)) {
    throw new FixUsageError('Expected SPECKIT_TWIN and SPECKIT_PULL as positive integers and SPECKIT_FOLDER as a spec folder name.');
  }
  const mode = FIX_MODES.includes(env.SPECKIT_MODE) ? env.SPECKIT_MODE : 'author';
  const amendment = Number(env.SPECKIT_AMENDMENT);
  if (mode !== 'author' && (!Number.isInteger(amendment) || amendment <= 0)) throw new FixUsageError(`Mode ${mode} needs SPECKIT_AMENDMENT (the spec pull request).`);
  return { twin, pull, folder, mode, amendment: mode === 'author' ? null : amendment, round: Math.max(0, Number(env.SPECKIT_ROUND) || 0), stalls: Math.max(0, Number(env.SPECKIT_STALLS) || 0) };
}

// Agent job of Spec Kit author, before the agent: what the agent needs and cannot fetch itself, in evidence.md and
// context.json. `author` writes a new spec for the stop of the implementation pull request (SPECKIT_FOLDER is the
// stopped spec); `fix` and `revise` rework the spec pull request SPECKIT_AMENDMENT (SPECKIT_FOLDER is the new spec).
export async function runEvidence({ client, env, log, now = Date.now }) {
  const { twin, pull: pullNumber, folder, mode, amendment, round, stalls } = inputsFrom(env);
  const outDir = path.resolve(env.SPECKIT_EVIDENCE_DIR || '.speckit-fix');
  mkdirSync(outDir, { recursive: true });
  const implementation = await client.getPullRequest(pullNumber);
  const blockedFolder = folderOfBranch(implementation.head?.ref);
  const baseBranch = baseBranchOf(implementation);
  const comments = await client.listIssueComments(pullNumber);
  const sections = [];
  let context;
  if (mode === 'author') {
    const stamp = /^\d{8}-\d{6}$/.test(String(env.SPECKIT_STAMP ?? '')) ? env.SPECKIT_STAMP : fixStamp(now());
    const requested = parseFixEvents(comments).filter((event) => event.event === 'requested').at(-1);
    const unlinked = requested?.link === false;
    const requestComment = requested ? comments.find((comment) => comment.id === requested.commentId) : null;
    const guidance = (requestComment ? parseGuidance(requestComment.body) : null) ?? (env.SPECKIT_GUIDANCE?.trim() || null);
    const diagnosis = comments.filter((comment) => comment.user?.login === BOT_LOGIN && String(comment.body ?? '').startsWith(DIAGNOSIS_COMMENT_MARKER)).at(-1);
    sections.push(
      unlinked ? `# Evidence for a new spec requested on #${pullNumber}` : `# Evidence for a new spec that unblocks #${pullNumber}`,
      '',
      `- ${unlinked ? 'Implementation' : 'Stopped spec'}: \`specs/${blockedFolder}\` (twin #${twin}), implementation pull request #${pullNumber} on \`${implementation.head?.ref}\``,
      ...(unlinked ? ['- The new spec does not block this implementation, which continues; the guidance below names what the spec must remove.'] : []),
      `- Base branch: \`${baseBranch}\` (the new spec is proposed against it)`,
      `- Requested by: ${requested?.by ? `@${requested.by}` : 'unknown'}`,
      '',
      '## Guidance from the person who asked for the new spec',
      '',
      guidance ?? '_None._',
      '',
      '## Latest diagnosis',
      '',
      diagnosis ? clip(diagnosis.body, 30_000) : '_None._',
      '',
      '## Recent pull request comments (oldest first)',
      '',
    );
    for (const comment of comments.slice(-12)) sections.push(`### ${comment.user?.login ?? 'unknown'} at ${comment.created_at}`, '', clip(comment.body, 6000), '');
    const existing = await existingFixSpecs(client, env);
    sections.push(
      '## Existing specs authored for stopped implementations',
      '',
      'One cause gets one spec. When one of these already removes the cause of this stop (the same root cause, even',
      'when another implementation asked for it), write nothing and report its pull request number in `reuse`; this',
      'implementation then waits for that spec and retries once it is implemented.',
      '',
    );
    if (existing.length === 0) sections.push('_None._', '');
    for (const item of existing) {
      sections.push(
        `### #${item.pull} ${clip(item.title, 200)} (\`specs/${item.folder}\`, ${item.state === 'open' ? 'open pull request' : `merged, waiting for the implementation of twin #${item.twin}`}${item.fixFor ? `, asked for by #${item.fixFor}` : ''})`,
        '',
        clip(item.spec ?? '_spec.md could not be read._', 8000),
        '',
      );
    }
    context = {
      mode,
      twin,
      pull: pullNumber,
      blockedFolder,
      prerequisiteOf: `specs/${blockedFolder}`,
      baseBranch,
      folderPrefix: `${stamp}-`,
      branchPrefix: SPEC_BRANCH_PREFIX,
      titlePrefix: FIX_TITLE_PREFIX,
      existingFixes: existing.map((item) => ({ pull: item.pull, folder: item.folder, state: item.state, title: item.title })),
    };
  } else {
    const fix = await client.getPullRequest(amendment);
    sections.push(
      `# Evidence for ${mode === 'fix' ? `correction round ${round} of` : 'a rework of'} spec #${amendment}`,
      '',
      `- Spec: \`specs/${folder}\` on \`${fix.head?.ref}\` against \`${fix.base?.ref}\``,
      `- It unblocks: #${pullNumber} (\`specs/${blockedFolder}\`, which depends on it)`,
      ...(mode === 'fix' ? [`- Rounds without progress so far: ${stalls} of ${MAX_STALLED_ROUNDS}`] : []),
      '',
      mode === 'fix' ? '## Findings of the consistency check to fix' : '## Feedback on the spec to address',
      '',
      env.SPECKIT_GUIDANCE?.trim() || '_None._',
      '',
      '## Earlier comments on the spec pull request (oldest first)',
      '',
    );
    for (const comment of (await client.listIssueComments(amendment)).slice(-10)) sections.push(`### ${comment.user?.login ?? 'unknown'} at ${comment.created_at}`, '', clip(comment.body, 4000), '');
    context = {
      mode,
      twin,
      pull: pullNumber,
      folder,
      specDir: `specs/${folder}`,
      fixPull: amendment,
      branch: isPrerequisiteBranch(fix.head?.ref) ? fix.head.ref : fixBranch(folder),
      baseBranch: fix.base?.ref ?? baseBranch,
      blockedFolder,
      prerequisiteOf: `specs/${blockedFolder}`,
      round,
      stalls,
      maxCorrectionRounds: MAX_CORRECTION_ROUNDS,
      maxStalledRounds: MAX_STALLED_ROUNDS,
    };
  }
  let evidence = sections.join('\n');
  if (Buffer.byteLength(evidence) > MAX_EVIDENCE_BYTES) evidence = `${evidence.slice(0, MAX_EVIDENCE_BYTES)}\n\n_(evidence truncated)_\n`;
  writeFileSync(path.join(outDir, 'evidence.md'), evidence);
  writeFileSync(path.join(outDir, 'context.json'), `${JSON.stringify(context, null, 2)}\n`);
  log(`Wrote the ${mode} evidence for #${pullNumber} to ${outDir}.`);
  return { exitCode: 0, context };
}

// A spec pull request authored by `/speckit author` may change its own spec folder and, for design decisions the
// spec makes, docs/architecture/.
export const isSpecPullPath = (folder, file) => file.startsWith(`specs/${folder}/`) || file.startsWith(ARCHITECTURE_PREFIX);

// The Design decisions comment on a spec pull request: one comment, by the workflow, that lists each architecture
// decision of the spec with why and the files it changes. The record jobs keep it current (syncDesignDecisions);
// checkFixSpec requires it when the pull request changes docs/architecture/.
export const DESIGN_DECISIONS_MARKER = '<!-- speckit-spec:design-decisions';
const DESIGN_DECISIONS_PATTERN = /^<!-- speckit-spec:design-decisions (\{[^\n]*?\}) -->/;
const MAX_DESIGN_DECISIONS = 20;

// Validates the untrusted `designDecisions` of a report: null when the report has none, otherwise the clipped list.
export function parseDesignDecisions(raw) {
  if (!Array.isArray(raw)) return null;
  const text = (value, max) => (typeof value === 'string' ? clip(value.trim(), max) : '');
  return raw.slice(0, MAX_DESIGN_DECISIONS)
    .map((item) => ({
      decision: text(item?.decision, 500),
      why: text(item?.why, 1000),
      files: (Array.isArray(item?.files) ? item.files : []).filter((file) => typeof file === 'string' && file.trim()).slice(0, 20).map((file) => clip(file.trim(), 200)),
    }))
    .filter((item) => item.decision);
}

export function renderDesignDecisions(decisions) {
  const lines = [
    `${DESIGN_DECISIONS_MARKER} ${JSON.stringify({ count: decisions.length })} -->`,
    '**Design decisions** of this spec (from the `## Architecture Updates` section of its plan). The changes to `docs/architecture/` follow from them; review them before you merge.',
    '',
  ];
  decisions.forEach((item, index) => {
    lines.push(`${index + 1}. **${neutralizeMarkers(item.decision)}**`);
    if (item.why) lines.push(`   - Why: ${neutralizeMarkers(item.why)}`);
    if (item.files.length > 0) lines.push(`   - Files: ${item.files.map((file) => `\`${neutralizeMarkers(file).replace(/`/g, '')}\``).join(', ')}`);
  });
  if (decisions.length === 0) lines.push('_None reported._');
  return lines.join('\n');
}

// The workflow's Design decisions comment on a spec pull request, and how many decisions it lists.
export async function designDecisionsComment(client, number) {
  const comment = (await client.listIssueComments(number))
    .filter((item) => item.user?.login === BOT_LOGIN && DESIGN_DECISIONS_PATTERN.test(String(item.body ?? '')))
    .at(-1);
  if (!comment) return null;
  let count = 0;
  try {
    count = Number(JSON.parse(String(comment.body).match(DESIGN_DECISIONS_PATTERN)[1]).count) || 0;
  } catch {
    // A damaged marker lists nothing.
  }
  return { ...comment, count };
}

// Creates or updates the Design decisions comment with the decisions a report gave; `null` (the report gave none)
// leaves it as it is, and an empty list only replaces an existing comment.
export async function syncDesignDecisions(client, number, decisions) {
  if (decisions === null) return null;
  const existing = await designDecisionsComment(client, number);
  const body = renderDesignDecisions(decisions);
  if (existing) {
    if (existing.body !== body) await client.updateComment(existing.id, body);
    return existing;
  }
  if (decisions.length === 0) return null;
  return client.createComment(number, body);
}

// Checks a spec pull request authored by `/speckit author`: it only adds a new spec folder (and, for the decisions
// its design makes, changes docs/architecture/, which then needs its Design decisions comment), and is ready for
// implementation like a published spec (publishBlockers). It needs no special marker: the dependency of the stopped
// spec on it is recorded on GitHub once it is merged. Every reason is a rule the consistency check's correction rounds
// fix.
export async function checkFixSpec(client, { folder, pull }) {
  const { architectureUpdates, publishBlockers } = await import('./speckit-author.mjs');
  const prefix = `specs/${folder}/`;
  const files = await client.listPullRequestFiles(pull.number);
  const changedPaths = [...new Set(files.flatMap((file) => [file.filename, file.previous_filename]).filter(Boolean))];
  const reasons = [];
  const outside = changedPaths.filter((file) => !isSpecPullPath(folder, file));
  if (outside.length > 0) reasons.push(`a spec authored by \`/speckit author\` may only add \`${prefix}\` and change \`${ARCHITECTURE_PREFIX}\` (specs/README.md lists no specs), but it changes ${outside.map((file) => `\`${file}\``).join(', ')}`);
  const architecture = changedPaths.filter((file) => file.startsWith(ARCHITECTURE_PREFIX));
  if (architecture.length > 0 && !((await designDecisionsComment(client, pull.number))?.count > 0)) {
    reasons.push(`it changes ${architecture.map((file) => `\`${file}\``).join(', ')}, but its plan lists no design decisions for it: name each decision behind these changes in the \`## Architecture Updates\` section of \`${prefix}plan.md\`, or revert the changes to \`${ARCHITECTURE_PREFIX}\``);
  }
  if (!isValidFolderName(folder) || !/^\d{8}-\d{6}-/.test(folder)) reasons.push(`the folder \`${folder}\` must start with a UTC time stamp (YYYYMMDD-HHMMSS-)`);
  if (await client.getFileContent(`${prefix}spec.md`, pull.base?.ref)) reasons.push(`\`${prefix}\` already exists on \`${pull.base?.ref}\`; a spec authored by \`/speckit author\` adds a new spec folder`);
  const head = pull.head?.sha ?? pull.head?.ref;
  const read = (file) => client.getFileContent(file, head);
  const specMarkdown = await read(`${prefix}spec.md`);
  const planMarkdown = await read(`${prefix}plan.md`);
  const tasksMarkdown = await read(`${prefix}tasks.md`);
  const checklists = [];
  for (const file of changedPaths.filter((item) => item.startsWith(`${prefix}checklists/`) && item.endsWith('.md'))) checklists.push((await read(file)) ?? '');
  reasons.push(...publishBlockers({
    folder,
    hasSpec: specMarkdown !== null,
    artifacts: [...(specMarkdown === null ? [] : ['spec.md']), ...(planMarkdown === null ? [] : ['plan.md']), ...(tasksMarkdown === null ? [] : ['tasks.md'])],
    tasksMarkdown,
    architecture: planMarkdown === null ? null : architectureUpdates(planMarkdown),
    openClarificationMarkers: (String(specMarkdown ?? '').match(/\[NEEDS CLARIFICATION/g) ?? []).length,
    openChecklistItems: countOpenChecklistItems(checklists),
  }));
  return { changedPaths, reasons, notes: [] };
}

// The result of the author job (result.json in SPECKIT_RESULT_DIR): what the decision step decided ({ decision:
// author | reuse | refuse, summary, refused, reuse }) and what the Spec Kit workflow `author` produced (outcome,
// folder, title, stage, error). Missing or unreadable, it says that the author job did not finish.
export function readResult(env) {
  const file = path.join(String(env.SPECKIT_RESULT_DIR || '.speckit-author'), 'result.json');
  const fallback = { decision: 'author', outcome: 'failed', error: `the author job did not finish (${String(env.SPECKIT_AUTHOR_JOB || 'no result')})` };
  if (!existsSync(file)) return fallback;
  try {
    return { ...fallback, ...JSON.parse(readFileSync(file, 'utf8')) };
  } catch {
    return fallback;
  }
}

// The author's report, from the result: { folder, summary, refused, reuse }. Only clipped strings and a pull request
// number are kept; `reuse` is checked against the existing specs before it is used.
export function parseAuthorReport(result) {
  const text = (value, max) => (typeof value === 'string' ? clip(value.trim(), max) : '');
  const reuse = Number(String(result?.reuse ?? '').replace(/^#/, ''));
  const failed = result?.decision === 'author' && result?.outcome !== 'authored';
  return {
    summary: text(result?.summary, 1500),
    refused: result?.decision === 'refuse' ? text(result?.refused, 1500) : failed ? text(result?.error, 1500) : '',
    folder: text(result?.folder, 200),
    reuse: result?.decision === 'reuse' && Number.isInteger(reuse) && reuse > 0 ? reuse : null,
  };
}

// The design decisions of a spec: the entries of the `## Architecture Updates` section of its plan.md, each with the
// docs/architecture/ files it names. The plan is the one source of the spec's architecture changes (constitution
// Principle I), so the Design decisions comment needs no report of its own; a section that says None lists none.
export function designDecisionsFromPlan(planMarkdown) {
  const lines = String(planMarkdown ?? '').replaceAll('\r\n', '\n').split('\n');
  const start = lines.findIndex((line) => /^##\s+Architecture Updates\s*$/.test(line.trim()));
  if (start === -1) return [];
  const body = [];
  for (const line of lines.slice(start + 1)) {
    if (/^##\s/.test(line)) break;
    body.push(line);
  }
  const first = body.map((line) => line.trim()).find(Boolean) ?? '';
  if (/^[*_`]*None\b/i.test(first)) return [];
  const decisions = [];
  let heading = '';
  for (const line of body) {
    const sub = line.match(/^#{3,}\s+(.+)$/);
    if (sub) {
      heading = sub[1].trim();
      continue;
    }
    const item = line.match(/^[-*]\s+(.+)$/);
    if (!item) continue;
    const text = item[1].trim();
    decisions.push({
      decision: clip(text.replace(/`/g, ''), 500),
      why: heading ? `plan.md § Architecture Updates, ${clip(heading, 200)}` : 'plan.md § Architecture Updates',
      files: [...new Set([...text.matchAll(/docs\/architecture\/[\w./#-]+/g)].map((match) => match[0].replace(/[#.]+$/, '').split('#')[0]))].slice(0, 20),
    });
  }
  return decisions.slice(0, MAX_DESIGN_DECISIONS);
}

// Keeps the Design decisions comment of a spec pull request in line with its plan at `ref`.
async function syncPlanDecisions(client, number, folder, ref) {
  try {
    const plan = await client.getFileContent(`specs/${folder}/plan.md`, ref);
    await syncDesignDecisions(client, number, designDecisionsFromPlan(plan));
  } catch {
    // The consistency check asks for the decisions again when they are missing.
  }
}

// Closes a spec pull request this run created and deletes its branch.
async function discardCreatedFix(client, number) {
  const pull = await client.getPullRequest(number);
  if (pull.state === 'open') await client.updatePullRequest(number, { state: 'closed' });
  if (isPrerequisiteBranch(pull.head?.ref)) {
    try {
      await client.deleteBranch(pull.head.ref);
    } catch {
      // Already gone.
    }
  }
}

// `/speckit author` found an existing spec for the same cause: the implementation waits for that one instead of a
// second spec. Records the same events as an authored spec (`created`, and `merged` when it is already merged), so the
// scheduler blocks and links it the same way (maintainFixSpec); the spec pull request is told.
async function joinFixSpec(client, env, { implementation, pullNumber, existing, summary, complete, log }) {
  const defaultBranch = defaultBranchOf(env);
  const merged = existing.state === 'merged';
  const block = fixBlock({ stage: merged ? 'implement' : 'review', fixPull: existing.pull, baseBranch: defaultBranch });
  const link = existing.url ? `[#${existing.pull}](${existing.url})` : `#${existing.pull}`;
  await client.createComment(pullNumber, [
    renderFixEvent('created', { pull: existing.pull, folder: existing.folder, joined: true }),
    ...(merged ? [renderFixEvent('merged', { pull: existing.pull, folder: existing.folder, joined: true })] : []),
    renderBlockedMarker(block.key),
    `**This stop has the same cause as spec ${link}** (\`specs/${existing.folder}\`), so no second spec was written: this implementation waits for that one and retries by itself once it is implemented.`,
    ...(summary ? ['', neutralizeMarkers(summary)] : []),
    '',
    ...block.lines,
  ].join('\n'));
  await client.createComment(existing.pull, `**Also unblocks #${pullNumber}** (\`specs/${folderOfBranch(implementation.head?.ref)}\`): \`/speckit author\` there found that this spec removes the same cause, so no second spec was written. #${pullNumber} retries by itself once this spec is implemented.`);
  await complete('success', `Joined spec #${existing.pull}`, summary || `The cause is the one spec #${existing.pull} removes.`);
  await setBlocked(client, pullNumber, true, { explain: block });
  log(`#${pullNumber}: joined spec #${existing.pull}.`);
  return { exitCode: 0, outcome: 'joined', pull: existing.pull };
}

// The outcome of a rework round of Spec Kit author for recordRework: the summary of what the Spec Kit workflow `author`
// reworked, the commit the land job pushed (SPECKIT_PUSH_SHA), and a push that failed (SPECKIT_PUSH_FAILURES).
export function reworkOutcome(result, env) {
  const pushed = String(env.SPECKIT_PUSH_SHA ?? '').trim();
  const pushFailures = Number(env.SPECKIT_PUSH_FAILURES || 0);
  if (result.outcome !== 'authored') {
    return { reasons: [result.error || 'the Spec Kit workflow `author` did not finish'], report: null, pushed: '', pushFailures: 0, incomplete: [] };
  }
  const stage = result.stage ? ` from ${result.stage}` : '';
  const summary = clip(result.summary || (result.files?.length > 0
    ? `The Spec Kit workflow \`author\` reworked the spec${stage}: ${result.files.map((file) => `\`${file}\``).join(', ')}.`
    : `The Spec Kit workflow \`author\` reworked the spec${stage} and changed nothing.`), 1500);
  return { reasons: [], report: { summary, responses: [] }, pushed, pushFailures, incomplete: result.pushRefused ? [result.pushRefused] : [] };
}

// Job `land` of Spec Kit author, after it published the result. `author`: validates the pull request it created, links
// it to the implementation, and starts its consistency check; a reuse, a refusal, a failed author run, or a broken pull
// request goes back to the implementation with the next steps. `fix` and `revise` are recorded like a rework of an
// amendment. The Design decisions come from the spec's plan (designDecisionsFromPlan).
export async function runRecord({ client, env, log }) {
  const inputs = inputsFrom(env);
  const result = readResult(env);
  if (inputs.mode !== 'author') {
    const pushed = String(env.SPECKIT_PUSH_SHA ?? '').trim();
    if (pushed) await syncPlanDecisions(client, inputs.amendment, inputs.folder, pushed);
    const { recordRework } = await import('./speckit-diagnose.mjs');
    return recordRework({ client, env, log, inputs: { ...inputs, findings: decodeTracked(env.SPECKIT_FINDINGS) }, outcome: reworkOutcome(result, env) });
  }
  const { twin, pull: pullNumber, folder: blockedFolder } = inputs;
  const implementation = await client.getPullRequest(pullNumber);
  const checkRun = Number(env.SPECKIT_CHECK_RUN);
  const complete = async (conclusion, title, summary) => {
    if (Number.isInteger(checkRun) && checkRun > 0) await closeAuthoringCheck(client, checkRun, conclusion, title, summary);
  };
  const report = parseAuthorReport(result);
  const created = Number(env.SPECKIT_CREATED_PULL);
  // A spec that does not block the implementation (`link: false`) never stops or holds it.
  const unlinked = parseFixEvents(await client.listIssueComments(pullNumber)).filter((event) => event.event === 'requested').at(-1)?.link === false;
  const nextSteps = async () => (unlinked
    ? ['This implementation is not affected and continues.']
    : renderNextSteps({ diagnosed: true, ...(await nextStepContext(client, implementation, blockedFolder)) }));
  const askPerson = async () => {
    if (!unlinked) await setAttention(client, pullNumber, true);
  };
  if (report?.reuse) {
    const existing = (await existingFixSpecs(client, env)).find((item) => item.pull === report.reuse && item.pull !== created);
    if (existing) {
      // One cause, one spec: a spec the agent created anyway for the same cause is discarded.
      if (Number.isInteger(created) && created > 0) await discardCreatedFix(client, created);
      if (unlinked) {
        const link = existing.url ? `[#${existing.pull}](${existing.url})` : `#${existing.pull}`;
        await client.createComment(pullNumber, [`**No new spec was written**: spec ${link} (\`specs/${existing.folder}\`) already removes this cause.`, ...(report.summary ? ['', neutralizeMarkers(report.summary)] : []), '', ...(await nextSteps())].join('\n'));
        await complete('success', `Covered by spec #${existing.pull}`, report.summary || `The cause is the one spec #${existing.pull} removes.`);
        log(`#${pullNumber}: the cause is covered by spec #${existing.pull}.`);
        return { exitCode: 0, outcome: 'joined', pull: existing.pull };
      }
      return joinFixSpec(client, env, { implementation, pullNumber, existing, summary: report.summary, complete, log });
    }
    if (!Number.isInteger(created) || created <= 0) {
      const why = `the decision named spec #${report.reuse} for this cause, but it is neither an open spec pull request authored by \`/speckit author\` nor a merged one that is still to be implemented`;
      await complete('failure', 'No spec was created', why);
      await client.createComment(pullNumber, [`**No spec was created**: ${why}.`, '', ...(await nextSteps())].join('\n'));
      await askPerson();
      log(`#${pullNumber}: invalid reuse of #${report.reuse}.`);
      return { exitCode: 0, outcome: 'none' };
    }
  }
  if (!Number.isInteger(created) || created <= 0) {
    const why = report.refused || report.summary || 'the Spec Kit workflow `author` did not create one';
    await complete('failure', 'No spec was created', why);
    await client.createComment(pullNumber, [`**No spec was created**: ${neutralizeMarkers(why)}`, '', ...(await nextSteps())].join('\n'));
    await askPerson();
    log(`#${pullNumber}: no spec was created.`);
    return { exitCode: 0, outcome: 'none' };
  }
  const pull = await client.getPullRequest(created);
  const fixFolder = folderOfBranch(pull.head?.ref);
  const defaultBranch = defaultBranchOf(env);
  const broken = [];
  if (!isPrerequisiteBranch(pull.head?.ref) || !fixFolder) broken.push(`its branch \`${pull.head?.ref}\` is not \`${SPEC_BRANCH_PREFIX}<folder>\``);
  if (pull.base?.ref !== defaultBranch) broken.push(`it targets \`${pull.base?.ref}\` instead of \`${defaultBranch}\``);
  if (pull.state !== 'open') broken.push('it is not open');
  if (fixFolder) {
    const files = await client.listPullRequestFiles(created);
    const outside = files.map((file) => file.filename).filter((file) => !isSpecPullPath(fixFolder, file));
    if (outside.length > 0) broken.push(`it changes files outside \`specs/${fixFolder}/\` and \`${ARCHITECTURE_PREFIX}\`: ${outside.map((file) => `\`${file}\``).join(', ')}`);
    if (await client.getFileContent(`specs/${fixFolder}/spec.md`, defaultBranch)) broken.push(`\`specs/${fixFolder}/\` already exists on \`${defaultBranch}\``);
  }
  if (broken.length > 0) {
    await discardCreatedFix(client, created);
    await complete('failure', 'The spec was rejected', broken.join('; '));
    await client.createComment(pullNumber, [`**The authored spec #${created} was rejected and closed**: ${broken.map(neutralizeMarkers).join('; ')}.`, '', ...(await nextSteps())].join('\n'));
    await askPerson();
    log(`#${pullNumber}: rejected spec #${created}.`);
    return { exitCode: 0, outcome: 'rejected' };
  }
  await client.updatePullRequest(created, { body: withoutComments(pull.body) });
  await syncPlanDecisions(client, created, fixFolder, pull.head?.sha ?? pull.head?.ref);
  const authored = `**Spec [${neutralizeMarkers(pull.title ?? `#${created}`)} (#${created})](${pull.html_url ?? ''}) was authored** for \`specs/${fixFolder}\`. An independent \`/speckit-analyze\` checks it for consistency first, and correction rounds fix what it finds; then it is merged automatically, or handed over for review when it changes \`${ARCHITECTURE_PREFIX}\` or a person pushed to it.`;
  if (unlinked) {
    await client.createComment(pullNumber, [
      renderFixEvent('created', { pull: created, folder: fixFolder, link: false }),
      `${authored} It does not block this implementation, which continues.`,
      ...(report?.summary ? ['', neutralizeMarkers(report.summary)] : []),
    ].join('\n'));
    await complete('success', `Spec #${created} authored`, report?.summary || `specs/${fixFolder}`);
    await beginAmendment(client, env, { amendment: await client.getPullRequest(created), folder: fixFolder, implementation, twin, kind: 'fix' });
    log(`#${pullNumber}: spec #${created} authored without blocking it; its consistency check started.`);
    return { exitCode: 0, outcome: 'created', pull: created };
  }
  const block = fixBlock({ stage: 'review', fixPull: created, baseBranch: defaultBranch });
  await client.createComment(pullNumber, [
    renderFixEvent('created', { pull: created, folder: fixFolder }),
    renderBlockedMarker(block.key),
    authored,
    ...(report?.summary ? ['', neutralizeMarkers(report.summary)] : []),
    '',
    ...block.lines,
  ].join('\n'));
  await complete('success', `Spec #${created} authored`, report?.summary || `specs/${fixFolder}`);
  await setBlocked(client, pullNumber, true, { explain: block });
  await beginAmendment(client, env, { amendment: await client.getPullRequest(created), folder: fixFolder, implementation, twin, kind: 'fix' });
  log(`#${pullNumber}: spec #${created} authored; its consistency check started.`);
  return { exitCode: 0, outcome: 'created', pull: created };
}

const isBotAccount = (user) => Boolean(user) && (user.type === 'Bot' || String(user.login ?? '').endsWith('[bot]') || user.login === BOT_LOGIN);

// Whether a commit comes from automation: its author and committer accounts are bots (GitHub's web-flow committer
// counts as neutral). A commit without a linked author account counts as automation only when its author name or
// email names a bot.
export function isAutomationCommit(commit) {
  const author = commit?.author;
  const authorIsBot = author
    ? isBotAccount(author)
    : /\[bot\]/.test(`${commit?.commit?.author?.name ?? ''} ${commit?.commit?.author?.email ?? ''}`);
  const committer = commit?.committer;
  const committerIsBot = !committer || committer.login === 'web-flow' || isBotAccount(committer);
  return authorIsBot && committerIsBot;
}

// Why a consistent spec pull request is not merged automatically but handed to a person: it changes
// docs/architecture/ (`architecture`), a person pushed to it (`push`), or a person's latest review requests changes
// (`changes`); null when it may be merged.
export async function specMergeHold(client, pull, changedPaths) {
  if (changedPaths.some((file) => file.startsWith(ARCHITECTURE_PREFIX))) return 'architecture';
  if ((await client.listPullRequestCommits(pull.number)).some((commit) => !isAutomationCommit(commit))) return 'push';
  const latest = new Map();
  for (const review of await client.listPullRequestReviews(pull.number)) {
    if (isBotAccount(review.user) || !review.user?.login || !['APPROVED', 'CHANGES_REQUESTED', 'DISMISSED'].includes(review.state)) continue;
    latest.set(review.user.login, review.state);
  }
  if ([...latest.values()].includes('CHANGES_REQUESTED')) return 'changes';
  return null;
}

// The automatic merge of a consistent spec pull request authored by `/speckit author` (Spec Kit analyze's record
// job): squash-merges it into the default branch unless specMergeHold holds it for a person, records the merge on the
// implementation pull request (settleClosedFix), and starts Spec Kit prepare (its twin) and Spec Kit orchestrate (the
// link), because events of the workflow token start no workflows. Returns `merged`, or `held` with the reason.
export async function mergeSpecPull(client, env, { amendment, folder, implementation }) {
  const pull = await client.getPullRequest(amendment.number);
  const files = await client.listPullRequestFiles(pull.number);
  const changedPaths = [...new Set(files.flatMap((file) => [file.filename, file.previous_filename]).filter(Boolean))];
  const held = await specMergeHold(client, pull, changedPaths);
  if (held) return { outcome: 'held', held };
  const defaultBranch = defaultBranchOf(env);
  if (pull.base?.ref !== defaultBranch) return { outcome: 'held', held: 'refused', message: `it targets \`${pull.base?.ref}\`` };
  if (pull.draft) await client.markReadyForReview(pull.node_id);
  const result = await client.mergePullRequest(pull.number, {
    sha: pull.head.sha,
    merge_method: 'squash',
    commit_title: `${pull.title ?? `Spec ${folder}`} (#${pull.number})`,
    commit_message: `Merged automatically by Spec Kit: consistent, no architecture changes, only automation commits. Authored with \`/speckit author\` on #${implementation.number}.`,
  });
  if (!result.merged) return { outcome: 'held', held: 'refused', message: result.message ?? 'the merge was refused' };
  const unlinked = parseFixEvents(await client.listIssueComments(implementation.number)).some((event) => event.event === 'created' && event.pull === pull.number && event.link === false);
  await client.createComment(pull.number, `**Merged automatically** into \`${defaultBranch}\`: an independent \`/speckit-analyze\` found it consistent, it changes no \`${ARCHITECTURE_PREFIX}\`, and only automation pushed to it. Its spec twin is created next; like every spec, it is implemented once someone with write access signs it off with \`/speckit implement\` on that twin.${unlinked ? '' : ` #${implementation.number} names the twin with the ready-to-paste command once it exists.`}`);
  await settleClosedFix(client, env, { amendment: await client.getPullRequest(pull.number), folder, implementation, automatic: true });
  for (const [file, inputs] of [[PREPARE_WORKFLOW_FILE, { dry_run: 'false' }], [ORCHESTRATE_WORKFLOW_FILE, {}]]) {
    try {
      await client.dispatchWorkflow(file, defaultBranch, inputs);
    } catch {
      // The push to the default branch and the hourly scheduler run start them.
    }
  }
  return { outcome: 'merged', sha: result.sha };
}

// Handles the merge or close of a spec pull request authored by `/speckit author` once (markers on the
// implementation pull request record it): a person's, or the automatic merge (`automatic`). A merge into the default
// branch waits for the twin, which the scheduler then links (maintainFixSpec).
export async function settleClosedFix(client, env, { amendment: pull, folder, implementation, actor = null, automatic = false }) {
  if (pull.state === 'open') return { outcome: 'open' };
  const events = parseFixEvents(await client.listIssueComments(implementation.number)).filter((event) => event.pull === pull.number);
  if (events.some((event) => ['merged', 'discarded'].includes(event.event))) return { outcome: 'handled' };
  const by = actor ? `@${actor}` : 'a person';
  const defaultBranch = defaultBranchOf(env);
  await setAttention(client, pull.number, false);
  try {
    await client.deleteBranch(isPrerequisiteBranch(pull.head?.ref) ? pull.head.ref : fixBranch(folder));
  } catch {
    // Already gone, or GitHub deleted it.
  }
  // A spec that does not block the implementation is recorded only; the implementation is never held or stopped by it.
  if (events.some((event) => event.event === 'created' && event.link === false)) {
    const merged = pull.merged_at && pull.base?.ref === defaultBranch;
    await client.createComment(implementation.number, [
      renderFixEvent(merged ? 'merged' : 'discarded', { pull: pull.number, folder, link: false }),
      merged
        ? `**Spec #${pull.number} was merged**${automatic ? ' automatically' : ` by ${by}`} into \`${defaultBranch}\`. It becomes a spec twin like any spec and is implemented once someone signs it off with \`/speckit implement\` on its twin; it does not block this implementation.`
        : `**Spec #${pull.number} was ${pull.merged_at ? `merged into \`${pull.base?.ref}\`` : 'closed without merging'}** by ${by}; it does not block this implementation, which is not affected.`,
    ].join('\n'));
    return { outcome: merged ? 'merged' : 'discarded' };
  }
  if (pull.merged_at && pull.base?.ref === defaultBranch) {
    const block = fixBlock({ stage: 'implement', fixPull: pull.number, baseBranch: defaultBranch });
    await client.createComment(implementation.number, [
      renderFixEvent('merged', { pull: pull.number, folder }),
      renderBlockedMarker(block.key),
      automatic
        ? `**Spec #${pull.number} was merged automatically** into \`${defaultBranch}\`: it is consistent, changes no \`${ARCHITECTURE_PREFIX}\`, and only automation pushed to it. It becomes a spec twin like any spec; this spec then depends on it, and it waits for sign-off with \`/speckit implement\` on its twin.`
        : `**Spec #${pull.number} was merged** into \`${defaultBranch}\` by ${by}. It becomes a spec twin like any spec; this spec then depends on it, and it waits for sign-off with \`/speckit implement\` on its twin.`,
      '',
      ...block.lines,
    ].join('\n'));
    return { outcome: 'merged' };
  }
  const context = await nextStepContext(client, implementation, folderOfBranch(implementation.head?.ref));
  const what = pull.merged_at
    ? `**Spec #${pull.number} was merged into \`${pull.base?.ref}\`** by ${by}, not into \`${defaultBranch}\`, so it is not implemented. The block is lifted, and this implementation stays stopped.`
    : `**Spec #${pull.number} was closed without merging** by ${by}. The block is lifted, and this implementation stays stopped.`;
  await client.createComment(implementation.number, [renderFixEvent('discarded', { pull: pull.number, folder }), what, '', ...renderNextSteps({ diagnosed: true, ...context })].join('\n'));
  await setBlocked(client, implementation.number, false);
  await setAttention(client, implementation.number, true);
  return { outcome: pull.merged_at ? 'misdirected' : 'discarded' };
}

// Makes spec twin `twin` depend on `prerequisite` (an ordinary blocked-by dependency). Never creates a cycle: when the
// prerequisite already depends on `twin`, nothing is added (`cycle`).
export async function linkPrerequisite(client, { twin, prerequisite }) {
  if ((await client.listBlockedBy(twin)).some((blocker) => blocker.number === prerequisite.number)) return { linked: true };
  if ((await client.listBlockedBy(prerequisite.number)).some((blocker) => blocker.number === twin)) return { linked: false, outcome: 'cycle' };
  try {
    await client.addBlockedBy(twin, prerequisite.id);
    return { linked: true };
  } catch (error) {
    return { linked: false, outcome: 'unlinked', error: error.message };
  }
}

function cycleNote(prerequisite, twin) {
  return `- Warning: spec twin #${prerequisite} already depends on #${twin}, so #${twin} cannot depend on it without a dependency cycle; remove the wrong one of the two dependencies.`;
}

// Scheduler side (Spec Kit orchestrate), for every implementation in progress: maintains the open pull request of the
// spec `/speckit author` authored for it like an amendment, settles a closed one, and once a merged one has a twin
// (after its dependency inference), makes this spec depend on it and names the twin with the command that signs it
// off. From then on the generic dependency handling (maintainDependencyBlock) blocks and retries the implementation.
// `blocked` tells whether the spec holds the implementation before that dependency exists. An authoring run that
// never reported is closed.
export async function maintainFixSpec(client, env, { implementation, twin }, { now = Date.now(), report = () => {} } = {}) {
  const comments = await client.listIssueComments(implementation.number);
  try {
    await maintainUnlinkedSpec(client, env, { implementation, twin, comments }, { now, report });
  } catch (error) {
    report(`- Warning: could not check the non-blocking spec of #${implementation.number}: ${error.message}`);
  }
  const state = fixState(comments);
  if (!state.created) {
    const latest = latestCheckRun(await client.listCheckRuns(implementation.head.sha, FIX_CHECK_NAME));
    if (latest && latest.status !== 'completed' && now - Date.parse(latest.started_at ?? latest.created_at ?? 0) >= AUTHORING_STALE_MS && !(await authoringRunning(client, twin, now))) {
      await closeAuthoringCheck(client, latest.id, 'failure', 'The spec authoring did not finish', 'The run ended without a result.');
      // An unfinished spec that would not have blocked the implementation does not stop it either.
      if (parseFixEvents(comments).filter((event) => event.event === 'requested').at(-1)?.link === false) {
        report(`- Closed the unfinished non-blocking spec authoring of #${implementation.number}.`);
        return { outcome: 'stale' };
      }
      await client.createComment(implementation.number, [`**The spec authoring did not finish**.`, '', ...renderNextSteps({ diagnosed: true, ...(await nextStepContext(client, implementation, folderOfBranch(implementation.head?.ref))) })].join('\n'));
      report(`- Closed the unfinished spec authoring of #${implementation.number}.`);
      await setAttention(client, implementation.number, true);
      return { outcome: 'stale' };
    }
    return { outcome: 'none' };
  }
  if (state.discarded || state.landed || state.stopped) return { outcome: 'done' };
  const fixFolder = state.created.folder;
  const pull = await client.getPullRequest(state.created.pull);
  const defaultBranch = defaultBranchOf(env);
  if (pull.state === 'open') {
    await setBlocked(client, implementation.number, true, { explain: fixBlock({ stage: 'review', fixPull: pull.number, baseBranch: defaultBranch }) });
    // A prerequisite spec that other implementations joined is maintained once, by the implementation it was authored
    // for while that one is open.
    const owner = state.created.joined ? await authoredFor(client, pull) : implementation.number;
    if (owner && owner !== implementation.number && (await client.getPullRequest(owner)).state === 'open') return { outcome: 'joined', blocked: true };
    await guardPullRequest(client, env, pull, { report });
    return { ...(await maintainOpenSpecPull(client, env, { amendment: await client.getPullRequest(pull.number), folder: fixFolder, implementation, twin, kind: 'fix' }, { now, report })), blocked: true };
  }
  if (!state.merged) {
    const settled = await settleClosedFix(client, env, { amendment: pull, folder: fixFolder, implementation, actor: pull.merged_by?.login ?? null });
    if (settled.outcome !== 'handled') report(`- Spec #${pull.number} was ${settled.outcome}.`);
    if (settled.outcome !== 'merged') return settled;
  }
  const hold = async () => {
    await setBlocked(client, implementation.number, true, { explain: fixBlock({ stage: 'implement', fixPull: pull.number, fixTwin: state.linked?.twin ?? null, baseBranch: defaultBranch }) });
    return true;
  };
  const prerequisite = state.linked
    ? await client.getIssue(state.linked.twin)
    : resolveTwins(await client.listTwinIssues(TWIN_LABEL)).byFolder.get(fixFolder);
  if (!prerequisite) {
    report(`- Spec #${pull.number} is merged; its twin does not exist yet.`);
    return { outcome: 'waiting', blocked: await hold() };
  }
  // A linked prerequisite is a dependency like any other, as long as the dependency exists.
  if (state.linked && (prerequisite.state !== 'open' || (await client.listBlockedBy(twin)).some((blocker) => blocker.number === prerequisite.number))) return { outcome: 'linked', blocked: false };
  // Dependency inference of the new twin runs first, so it never sees (and is never rejected for) a cycle with this
  // link.
  if (hasLabel(prerequisite, PENDING_LABEL)) {
    report(`- Spec #${pull.number} is spec twin #${prerequisite.number}; it waits for its dependency inference before #${twin} depends on it.`);
    return { outcome: 'waiting', blocked: await hold() };
  }
  const link = await linkPrerequisite(client, { twin, prerequisite });
  if (!link.linked) {
    report(link.outcome === 'cycle' ? cycleNote(prerequisite.number, twin) : `- Warning: could not make #${twin} depend on prerequisite #${prerequisite.number}: ${link.error}`);
    return { outcome: link.outcome, blocked: await hold() };
  }
  if (state.linked) return { outcome: 'linked', blocked: false };
  // Like every spec, the new twin starts only once someone signs it off with `/speckit implement`; the comment names
  // the twin with that command, and the block it explains is the generic dependency block.
  const requester = state.requested?.by ?? null;
  const block = await explainDependencyBlock(client, (await client.listBlockedBy(twin)).filter((blocker) => blocker.state === 'open'));
  await client.createComment(implementation.number, [
    renderFixEvent('linked', { pull: pull.number, folder: fixFolder, twin: prerequisite.number }),
    renderBlockedMarker(block.key),
    `**Spec #${pull.number} is spec twin [#${prerequisite.number}](${prerequisite.html_url ?? `#${prerequisite.number}`})**, and this spec now depends on it.${requester ? ` @${requester}, you asked for it with \`/speckit author\`:` : ''} it is implemented once someone with write access signs it off with \`/speckit implement\` on #${prerequisite.number}; this implementation retries by itself once #${prerequisite.number} is implemented.`,
    '',
    ...block.lines,
  ].join('\n'));
  try {
    await client.dispatchWorkflow(ORCHESTRATE_WORKFLOW_FILE, defaultBranchOf(env), {});
  } catch {
    // The hourly scheduler run starts it.
  }
  report(`- Linked spec #${pull.number} (twin #${prerequisite.number}) to #${implementation.number}.`);
  return { outcome: 'linked', blocked: false };
}

// Maintains the open pull request of a spec that does not block the implementation (`link: false`) like any authored
// spec, and records once that it was merged or closed; the implementation is never held, linked, or stopped by it.
async function maintainUnlinkedSpec(client, env, { implementation, twin, comments }, { now, report }) {
  const state = fixState(comments, { unlinked: true });
  if (!state.created || state.merged || state.discarded) return { outcome: 'none' };
  const pull = await client.getPullRequest(state.created.pull);
  if (pull.state === 'open') {
    await guardPullRequest(client, env, pull, { report });
    return maintainOpenSpecPull(client, env, { amendment: await client.getPullRequest(pull.number), folder: state.created.folder, implementation, twin, kind: 'fix' }, { now, report });
  }
  const settled = await settleClosedFix(client, env, { amendment: pull, folder: state.created.folder, implementation, actor: pull.merged_by?.login ?? null });
  if (settled.outcome !== 'handled') report(`- Non-blocking spec #${pull.number} was ${settled.outcome}.`);
  return settled;
}

async function authoringRunning(client, twin, now) {
  const since = new Date(now - 2 * AUTHORING_STALE_MS).toISOString();
  const runs = (await client.listWorkflowRuns(FIX_WORKFLOW_FILE, since, 1)).filter((run) => isTwinRunOf(FIX_WORKFLOW_FILE, run.display_title, twin));
  return runs.some((run) => run.status !== 'completed');
}

// ── Job `author` of Spec Kit author (read-only): the decision, the inputs of the Spec Kit workflow, and the result ──

export const DECISIONS = ['author', 'reuse', 'refuse'];
const MAX_FEATURE = 8000;
const resultDir = (env) => path.resolve(String(env.SPECKIT_RESULT_DIR || '.speckit-author'));
const writeOutputs = (env, outputs) => {
  if (env.GITHUB_OUTPUT) appendFileSync(env.GITHUB_OUTPUT, Object.entries(outputs).map(([key, value]) => `${key}=${value}\n`).join(''));
};

// Validates the decision step's decision.json: `author` with the feature description for /speckit-specify, `reuse`
// with the pull request number of an existing spec that removes the cause, or `refuse` with why no spec can remove it.
export function validateDecision(data) {
  const reasons = [];
  const decision = data?.decision;
  if (!DECISIONS.includes(decision)) reasons.push(`"decision" must be one of ${DECISIONS.join(', ')}`);
  const text = (value) => (typeof value === 'string' ? value.trim() : '');
  if (decision === 'author' && !text(data.feature)) reasons.push('"feature" (the feature description) is missing');
  if (decision === 'author' && text(data.feature).length > MAX_FEATURE) reasons.push(`"feature" is longer than ${MAX_FEATURE} characters`);
  const reuse = Number(String(data?.reuse ?? '').replace(/^#/, ''));
  if (decision === 'reuse' && !(Number.isInteger(reuse) && reuse > 0)) reasons.push('"reuse" must be the number of the existing spec pull request');
  if (decision === 'refuse' && !text(data.refused)) reasons.push('"refused" (why no spec can remove the cause) is missing');
  if (reasons.length > 0) return { reasons, decision: null };
  return {
    reasons,
    decision: {
      decision,
      summary: clip(text(data.summary), 1500),
      ...(decision === 'author' ? { feature: text(data.feature) } : {}),
      ...(decision === 'reuse' ? { reuse } : {}),
      ...(decision === 'refuse' ? { refused: clip(text(data.refused), 1500) } : {}),
    },
  };
}

// After the decision step: validates decision.json into decision-validated.json and feature.txt, and resets the
// workspace, so nothing the decision step changed reaches the spec. An invalid decision becomes a refusal that says so.
export function runDecide({ env, log, git }) {
  const dir = resultDir(env);
  const file = path.join(dir, 'decision.json');
  let data = null;
  let problem = '';
  try {
    data = JSON.parse(readFileSync(file, 'utf8'));
  } catch (error) {
    problem = existsSync(file) ? `decision.json is not valid JSON: ${error.message}` : 'the decision step wrote no decision.json';
  }
  const validated = data ? validateDecision(data) : { reasons: [problem], decision: null };
  const decision = validated.decision ?? { decision: 'refuse', summary: '', refused: `The decision step did not decide: ${validated.reasons.join('; ')}.` };
  writeFileSync(path.join(dir, 'decision-validated.json'), `${JSON.stringify(decision, null, 2)}\n`);
  writeFileSync(path.join(dir, 'feature.txt'), decision.feature ?? '');
  git(['checkout', '--', '.']);
  git(['clean', '-fdq', `--exclude=${path.basename(dir)}`]);
  writeOutputs(env, { decision: decision.decision });
  log(`Decision: ${decision.decision}${validated.reasons.length > 0 ? ` (${validated.reasons.join('; ')})` : ''}.`);
  return { exitCode: 0, outcome: decision.decision };
}

// The stage a rework starts at: the earliest artifact its findings or feedback name (spec.md: clarify; plan.md and its
// design artifacts: plan; tasks.md: tasks), otherwise `fallback`. Later stages always run again after it.
export function reworkStage(text, fallback) {
  const value = String(text ?? '');
  if (/\bspec\.md\b/.test(value)) return 'clarify';
  if (/\b(plan|research|data-model|quickstart)\.md\b|\bcontracts\//.test(value)) return 'plan';
  if (/\btasks\.md\b/.test(value)) return 'tasks';
  return fallback;
}

// Before the Spec Kit workflow runs a rework: its feedback (feedback.txt) and the stage it starts at. Consistency
// findings (`fix`) mostly concern the coverage of the tasks; a person's feedback (`revise`) may concern anything.
export function runInputs({ env, log }) {
  const inputs = inputsFrom(env);
  const dir = resultDir(env);
  mkdirSync(dir, { recursive: true });
  const guidance = String(env.SPECKIT_GUIDANCE ?? '').trim();
  const stage = reworkStage(guidance, inputs.mode === 'fix' ? 'tasks' : 'clarify');
  const feedback = inputs.mode === 'fix'
    ? `Resolve these findings of the consistency check (correction round ${inputs.round}):\n\n${guidance}`
    : `Address this feedback from the review of the spec pull request:\n\n${guidance}`;
  writeFileSync(path.join(dir, 'feedback.txt'), feedback);
  writeOutputs(env, { stage });
  log(`The ${inputs.mode} reworks specs/${inputs.folder} from ${stage}.`);
  return { exitCode: 0, outcome: stage };
}

// After the Spec Kit workflow: result.json (the decision and what the run produced) and changes.patch (the commit the
// run made with publish=commit, from SPECKIT_START), for job `land`.
export async function runPackage({ env, log, git, rootDir = process.cwd() }) {
  const inputs = inputsFrom(env);
  const dir = resultDir(env);
  const decision = inputs.mode === 'author'
    ? JSON.parse(readFileSync(path.join(dir, 'decision-validated.json'), 'utf8'))
    : { decision: 'author', summary: '' };
  const result = { ...decision, stage: env.SPECKIT_STAGE || null };
  if (decision.decision === 'author') {
    const { pending, readState } = await import('./speckit-author-flow.mjs');
    const runFile = path.join(dir, 'run.json');
    const run = existsSync(runFile) ? (readFileSync(runFile, 'utf8').match(/"run_id"\s*:\s*"([\w-]+)"/)?.[1] ?? '') : '';
    const state = /^[\w-]+$/.test(run) ? pending({ rootDir, run }) : { status: 'failed', error: 'the Spec Kit workflow `author` did not start' };
    // On GitHub every run is unattended and must finish in this job; a run that paused stopped at a gate, which is a
    // defect of the workflow, not of the spec.
    if (state.status === 'paused') state.error = `a gate (${state.step}) paused the unattended run, which must never ask; the workflow \`author\` has a defect`;
    const start = String(env.SPECKIT_START ?? '').trim();
    const files = state.status === 'completed' ? git(['diff', '--name-only', '--no-renames', start, 'HEAD']).stdout.split(/\r?\n/).filter(Boolean) : [];
    Object.assign(result, {
      outcome: state.status === 'completed' ? 'authored' : 'failed',
      folder: state.folder ?? null,
      title: /^[\w-]+$/.test(run) ? readState(rootDir, run).title ?? null : null,
      files,
      ...(state.status === 'completed' ? {} : { error: clip(state.error || `the Spec Kit workflow \`author\` ended ${state.status}`, 3000) }),
    });
    if (files.length > 0) writeFileSync(path.join(dir, 'changes.patch'), git(['diff', '--binary', '--no-renames', start, 'HEAD']).stdout);
  }
  writeFileSync(path.join(dir, 'result.json'), `${JSON.stringify(result, null, 2)}\n`);
  log(`Result: ${result.decision}${result.outcome ? ` ${result.outcome}` : ''}${result.folder ? ` specs/${result.folder}` : ''}.`);
  return { exitCode: 0, outcome: result.outcome ?? result.decision };
}

// ── Job `land` of Spec Kit author (write token, never runs agent-written code) ─────────────────────────────────────

const BOT_IDENTITY = ['-c', 'user.name=github-actions[bot]', '-c', 'user.email=41898282+github-actions[bot]@users.noreply.github.com'];

function remoteArgs(env, ...args) {
  const server = (env.GITHUB_SERVER_URL || 'https://github.com').replace(/\/$/, '');
  const basic = Buffer.from(`x-access-token:${env.GITHUB_TOKEN}`).toString('base64');
  return ['-c', `http.${server}/.extraheader=AUTHORIZATION: basic ${basic}`, ...args.map((arg) => (arg === '<remote>' ? `${server}/${env.GITHUB_REPOSITORY}.git` : arg))];
}

// Applies changes.patch to the workspace and commits it: only the spec folder and docs/architecture/ may change.
function applyResult(git, dir, folder, message, { threeWay = false } = {}) {
  const patch = path.join(dir, 'changes.patch');
  const applied = git(['apply', ...(threeWay ? ['--3way'] : []), '--index', '--whitespace=nowarn', patch]);
  if (applied.status !== 0) return { error: `the change does not apply to the branch: ${(applied.stderr || applied.stdout).trim().slice(0, 500)}` };
  const changed = git(['diff', '--cached', '--name-only', '--no-renames']).stdout.split(/\r?\n/).filter(Boolean);
  const outside = changed.filter((file) => !isSpecPullPath(folder, file));
  if (outside.length > 0) return { error: `it changes files outside \`specs/${folder}/\` and \`${ARCHITECTURE_PREFIX}\`: ${outside.map((file) => `\`${file}\``).join(', ')}` };
  if (changed.length === 0) return { sha: null, changed };
  const committed = git([...BOT_IDENTITY, 'commit', '--quiet', '-m', message]);
  if (committed.status !== 0) return { error: `the commit failed: ${(committed.stderr || committed.stdout).trim().slice(0, 500)}` };
  return { sha: git(['rev-parse', 'HEAD']).stdout.trim(), changed };
}

// `author`: commits the new spec on speckit-spec/<folder> (a branch this run creates) and opens its draft pull request.
async function landNewSpec({ client, env, git, result, dir }) {
  const folder = String(result.folder ?? '');
  if (!isValidFolderName(folder) || !/^\d{8}-\d{6}-/.test(folder)) return { error: `the Spec Kit workflow reported no valid spec folder (\`${folder}\`)` };
  if (!existsSync(path.join(dir, 'changes.patch'))) return { error: 'the Spec Kit workflow `author` committed no spec' };
  const branch = `${SPEC_BRANCH_PREFIX}${folder}`;
  if (await client.getBranchSha(branch)) return { error: `the branch \`${branch}\` already exists` };
  const title = clip(String(result.title || folder).replace(/\s+/g, ' ').trim(), 200);
  const landed = applyResult(git, dir, folder, `${FIX_TITLE_PREFIX}${title}`);
  if (landed.error) return landed;
  if (!landed.changed.includes(`specs/${folder}/spec.md`)) return { error: `the change has no \`specs/${folder}/spec.md\`` };
  const pushed = git(remoteArgs(env, 'push', '--quiet', '<remote>', `HEAD:refs/heads/${branch}`));
  if (pushed.status !== 0) return { error: `the push of \`${branch}\` failed: ${(pushed.stderr || pushed.stdout).trim().slice(0, 500)}` };
  let pull;
  try {
    pull = await client.createPullRequest({
      title: `${FIX_TITLE_PREFIX}${title}`,
      head: branch,
      base: defaultBranchOf(env),
      body: [result.summary || `Spec \`specs/${folder}\`.`, '', `Authored by the Spec Kit workflow \`author\` for #${env.SPECKIT_PULL}.`].join('\n'),
      draft: true,
    });
  } catch (error) {
    await client.deleteBranch(branch).catch(() => {});
    return { error: `the pull request could not be created: ${error.message}` };
  }
  return { pull: pull.number };
}

// `fix` and `revise`: commits the rework on the spec pull request's branch (a person's push meanwhile is merged
// three-way); a change that no longer applies or a refused push is a round without progress.
function landRework({ env, git, result, dir, folder }) {
  if (result.outcome !== 'authored' || !existsSync(path.join(dir, 'changes.patch'))) return {};
  const landed = applyResult(git, dir, folder, `Rework specs/${folder}${result.stage ? ` from ${result.stage}` : ''}`, { threeWay: true });
  if (landed.error) return { pushRefused: landed.error };
  if (!landed.sha) return {};
  const branch = git(['rev-parse', '--abbrev-ref', 'HEAD']).stdout.trim();
  const pushed = git(remoteArgs(env, 'push', '--quiet', '<remote>', `HEAD:refs/heads/${branch}`));
  if (pushed.status !== 0) return { pushFailures: 1 };
  return { pushed: landed.sha };
}

// Job `land`: publishes the author job's result (a new spec pull request, or the rework pushed to its branch) and
// records it (runRecord). The workspace is the default branch (`author`) or the spec pull request's branch.
export async function runLand({ client, env, log, git }) {
  const inputs = inputsFrom(env);
  const dir = resultDir(env);
  mkdirSync(dir, { recursive: true });
  const result = readResult(env);
  const extra = {};
  if (inputs.mode === 'author') {
    if (result.decision === 'author' && result.outcome === 'authored') {
      const landed = await landNewSpec({ client, env, git, result, dir });
      if (landed.error) Object.assign(result, { outcome: 'failed', error: `The new spec could not be published: ${landed.error}.` });
      else extra.SPECKIT_CREATED_PULL = String(landed.pull);
    }
  } else {
    const landed = landRework({ env, git, result, dir, folder: inputs.folder });
    if (landed.pushRefused) result.pushRefused = landed.pushRefused;
    if (landed.pushed) extra.SPECKIT_PUSH_SHA = landed.pushed;
    if (landed.pushFailures) extra.SPECKIT_PUSH_FAILURES = String(landed.pushFailures);
  }
  writeFileSync(path.join(dir, 'result.json'), `${JSON.stringify(result, null, 2)}\n`);
  return runRecord({ client, env: { ...env, ...extra }, log });
}

export async function main(argv, { env = process.env, log = console.log, client, git } = {}) {
  const [command] = argv;
  const workspace = path.resolve(String(env.SPECKIT_WORKSPACE || '.'));
  const handlers = { evidence: runEvidence, decide: runDecide, inputs: runInputs, package: runPackage, land: runLand, record: runRecord };
  if (!handlers[command]) throw new FixUsageError(`Usage: speckit-fix.mjs <${Object.keys(handlers).join(' | ')}>`);
  // decide, inputs, and package run in the read-only author job without a GitHub token.
  const needsClient = ['evidence', 'land', 'record'].includes(command);
  const run = { client: client ?? (needsClient ? createGitHubClient(env) : null), env, log, git: git ?? defaultGit(workspace), rootDir: workspace };
  const result = await handlers[command](run);
  if (env.GITHUB_OUTPUT) appendFileSync(env.GITHUB_OUTPUT, `outcome=${result.outcome ?? ''}\n`);
  return result.exitCode;
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  main(process.argv.slice(2)).then(
    (code) => {
      process.exitCode = code;
    },
    (error) => {
      console.error(error.message);
      process.exitCode = error instanceof FixUsageError ? 2 : 1;
    },
  );
}
